    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time


def _feasible_radii(X, Y):
    """Given centers, compute the largest feasible radii (iterative)."""
    n = len(X)
    r = np.minimum(np.minimum(X, 1 - X), np.minimum(Y, 1 - Y))
    for _ in range(150):
        changed = False
        for i in range(n):
            m = min(X[i], 1 - X[i], Y[i], 1 - Y[i])
            for j in range(n):
                if i == j:
                    continue
                d = np.hypot(X[i] - X[j], Y[i] - Y[j]) - r[j]
                if d < m:
                    m = d
            if m < r[i] - 1e-12 or m > r[i] + 1e-12:
                r[i] = m
                changed = True
        if not changed:
            break
    return np.maximum(r, 1e-9)


def _relax(X, Y, R, iters=80):
    """Push centers apart to satisfy radii constraints, keep in box."""
    n = len(X)
    for _ in range(iters):
        moved = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = X[j] - X[i]
                dy = Y[j] - Y[i]
                d = np.hypot(dx, dy)
                s = R[i] + R[j]
                if d < s:
                    if d < 1e-12:
                        dx, dy, d = 1e-6, 0.0, 1e-6
                    push = (s - d) * 0.5
                    ux, uy = dx / d, dy / d
                    X[i] -= ux * push
                    Y[i] -= uy * push
                    X[j] += ux * push
                    Y[j] += uy * push
                    moved = True
        for i in range(n):
            if X[i] < R[i]:
                X[i] = R[i]
            elif X[i] > 1 - R[i]:
                X[i] = 1 - R[i]
            if Y[i] < R[i]:
                Y[i] = R[i]
            elif Y[i] > 1 - R[i]:
                Y[i] = 1 - R[i]
        if not moved:
            break
    return X, Y


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.82
    n = 32
    rng = np.random.default_rng(20240117)

    # Initial configuration from start (trust it) or grid
    if start is not None:
        S = np.asarray(start, dtype=float)
        if S.shape != (n, 3):
            S = None
    else:
        S = None

    if S is not None:
        X = S[:, 0].copy()
        Y = S[:, 1].copy()
    else:
        k = 6
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        X = np.array([p[0] for p in pts])
        Y = np.array([p[1] for p in pts])

    R = _feasible_radii(X, Y)
    best_X, best_Y, best_R = X.copy(), Y.copy(), R.copy()
    best_score = R.sum()

    restart = 0
    while time.process_time() - t0 < budget:
        if restart == 0:
            X, Y = best_X.copy(), best_Y.copy()
        elif restart % 3 == 0:
            # fresh random layout
            X = rng.uniform(0.05, 0.95, n)
            Y = rng.uniform(0.05, 0.95, n)
        else:
            # perturb best
            sig = 0.05 if restart % 3 == 1 else 0.02
            X = np.clip(best_X + rng.normal(0, sig, n), 0.01, 0.99)
            Y = np.clip(best_Y + rng.normal(0, sig, n), 0.01, 0.99)
        R = _feasible_radii(X, Y)
        restart += 1

        # Growth-relax loop
        for _ in range(300):
            if time.process_time() - t0 >= budget:
                break
            R = R * 1.04
            X, Y = _relax(X, Y, R, iters=60)
            R = _feasible_radii(X, Y)
            sc = R.sum()
            if sc > best_score:
                best_score = sc
                best_X, best_Y, best_R = X.copy(), Y.copy(), R.copy()

        # Coordinate-wise local search using feasible_radii as score
        X, Y = best_X.copy(), best_Y.copy()
        R = _feasible_radii(X, Y)
        cur = R.sum()
        step = 0.008
        while time.process_time() - t0 < budget:
            improved = False
            for _ in range(40):
                i = rng.integers(n)
                dX = X.copy()
                dY = Y.copy()
                delta = rng.normal(0, step)
                if rng.random() < 0.5:
                    dX[i] = np.clip(dX[i] + delta, 0.001, 0.999)
                else:
                    dY[i] = np.clip(dY[i] + delta, 0.001, 0.999)
                dR = _feasible_radii(dX, dY)
                sc = dR.sum()
                if sc > cur + 1e-12:
                    X, Y, R = dX, dY, dR
                    cur = sc
                    improved = True
                    if sc > best_score:
                        best_score = sc
                        best_X, best_Y = X.copy(), Y.copy()
                        best_R = R.copy()
            if not improved:
                step *= 0.7
                if step < 1e-5:
                    break

    # Final feasibility and safety margin
    X, Y, R = best_X.copy(), best_Y.copy(), best_R.copy()
    R = _feasible_radii(X, Y)
    R *= (1 - 1e-9)
    R = np.maximum(R, 1e-9)
    out = np.column_stack([X, Y, R])

    for _ in range(30):
        ok = True
        for i in range(n):
            if out[i, 2] <= 0 or out[i, 0] - out[i, 2] < 0 or out[i, 0] + out[i, 2] > 1 \
               or out[i, 1] - out[i, 2] < 0 or out[i, 1] + out[i, 2] > 1:
                ok = False
                break
        if ok:
            for i in range(n):
                for j in range(i + 1, n):
                    d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                    if d < out[i, 2] + out[j, 2]:
                        ok = False
                        break
                if not ok:
                    break
        if ok:
            break
        out[:, 2] *= 0.999

    return out
